{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 public access is not explicitly blocked",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "MEDIUM",
      "explanation": "The bucket lacks an S3 Public Access Block, and its ACL is supplied through a variable that could permit public access. This leaves the bucket dependent on caller-supplied ACL values and account-level settings."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is disabled",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "HIGH",
      "explanation": "The bucket does not enable versioning, reducing protection against accidental deletion, overwrites, and destructive activity."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 access logging is disabled",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "HIGH",
      "explanation": "No access logging configuration is present, limiting auditability and investigation of access to the bucket."
    },
    {
      "check_id": "CKV_AWS_144",
      "title": "S3 cross-region replication is disabled",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "MEDIUM",
      "explanation": "The bucket has no replication configuration, so its encrypted data is not protected by a policy-compliant cross-region replica."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "S3 lifecycle configuration is missing",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "MEDIUM",
      "explanation": "The bucket lacks lifecycle controls, including cleanup of abandoned multipart uploads that can otherwise persist indefinitely."
    }
  ],
  "patched_code": "variable "access_log_bucket" {
  description = "Name of the preconfigured S3 bucket that receives server access logs."
  type        = string
}

variable "replication_role_arn" {
  description = "ARN of the IAM role authorized to replicate objects from this bucket."
  type        = string
}

variable "replication_destination_bucket_arn" {
  description = "ARN of the destination S3 bucket in the replication region."
  type        = string
}

variable "replication_destination_kms_key_arn" {
  description = "ARN of the KMS key in the replication region used to encrypt replicas."
  type        = string
}

resource "aws_s3_bucket" "bucket_2" {
  bucket = "roger-bucket-2"
  acl    = "private"

  versioning {
    enabled = true
  }

  logging {
    target_bucket = var.access_log_bucket
    target_prefix = "roger-bucket-2/"
  }

  lifecycle_rule {
    id      = "abort-incomplete-multipart-uploads"
    enabled = true

    abort_incomplete_multipart_upload_days = 7
  }

  replication_configuration {
    role = var.replication_role_arn

    rules {
      id     = "cross-region-replication"
      prefix = ""
      status = "Enabled"

      source_selection_criteria {
        sse_kms_encrypted_objects {
          enabled = true
        }
      }

      destination {
        bucket             = var.replication_destination_bucket_arn
        replica_kms_key_id = var.replication_destination_kms_key_arn
        storage_class      = "STANDARD"
      }
    }
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        kms_master_key_id = aws_kms_key.my_key.arn
        sse_algorithm     = "aws:kms"
      }
    }
  }
}

resource "aws_s3_bucket_public_access_block" "bucket_2" {
  bucket = aws_s3_bucket.bucket_2.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}
",
  "fix_summary": "Enforced a private ACL and comprehensive public-access blocking, then enabled versioning, access logging, lifecycle cleanup, and KMS-aware cross-region replication. External logging and replication infrastructure is supplied through required variables rather than embedding credentials or placeholder resources."
}
